const mensajeCliente = $('Telegram Trigger').first().json.message.text;
const productos = $('Get row(s) in sheet').all();
const catalogo = productos.map(p => {
  const d = p.json;
  return d.id + ' | ' + d.modelo + ' | ' + d.tipo_espacio + ' | ' + d.descripcion + ' | Precio: $' + d.precio_venta + ' MXN';
}).join(' // ');

const systemPrompt = 'Eres Valeria, asesora de ventas de Zummat, empresa mexicana de iluminacion LED TecnoLED. Tu tono es amigable, profesional y conciso. Respondes SIEMPRE en español. CATALOGO ZUMMAT: ' + catalogo + ' REGLAS: 1) Solo recomienda productos del catalogo. 2) Selecciona EXACTAMENTE 3 productos que mejor se adapten. 3) Presenta nombre para que sirve y precio en MXN. 4) Si no sabes que espacio tiene el cliente preguntale primero. 5) NUNCA inventes productos fuera del catalogo.';

const requestBody = JSON.stringify({
  model: 'deepseek/deepseek-chat-v3.1',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: mensajeCliente }
  ]
});

return [{ json: { requestBody } }];

const chatId = $('Telegram Trigger').first().json.message.chat.id;
const input = $input.item.json;
let texto = '';

if (input.body) {
  try {
    const parsed = JSON.parse(input.body);
    texto = parsed.choices[0].message.content;
  } catch(e) { texto = 'Hubo un error, intenta de nuevo.'; }
} else if (input.choices) {
  texto = input.choices[0].message.content;
}

if (!texto) texto = 'Hubo un error, intenta de nuevo.';
const textoLimpio = texto.split('\n\nThis message')[0].trim();
return [{ json: { texto: textoLimpio, chatId: Number(chatId) } }];
